import jakarta.persistence.*;
import java.io.PrintWriter;

public class EventService {

    private static final EntityManagerFactory emf =
            Persistence.createEntityManagerFactory("events-pu");

    private static final int MAX_TIPO_LENGTH = 100;
    private static final int MAX_DESCRICAO_LENGTH = 1000;

    public Long salvarEvento(String tipo, String descricao, PrintWriter responseWriter) {
        validateInput(tipo, descricao);

        String sanitizedTipo = sanitize(tipo, MAX_TIPO_LENGTH);
        String sanitizedDescricao = sanitize(descricao, MAX_DESCRICAO_LENGTH);

        EntityManager em = emf.createEntityManager();
        EntityTransaction tx = em.getTransaction();

        try {
            tx.begin();
            Event event = new Event(sanitizedTipo, sanitizedDescricao);
            em.persist(event);
            tx.commit();

            Long savedId = event.getId();

            if (responseWriter != null) {
                responseWriter.write("Event saved successfully with ID: " + savedId);
                responseWriter.flush();
            }

            return savedId;

        } catch (Exception e) {
            if (tx != null && tx.isActive()) {
                tx.rollback();
            }
            throw new RuntimeException("Failed to save event", e);
        } finally {
            if (em != null && em.isOpen()) {
                em.close();
            }
        }
    }

    private void validateInput(String tipo, String descricao) {
        if (tipo == null || tipo.isBlank()) {
            throw new IllegalArgumentException("tipo must not be null or blank");
        }
        if (descricao == null || descricao.isBlank()) {
            throw new IllegalArgumentException("descricao must not be null or blank");
        }
        if (tipo.length() > MAX_TIPO_LENGTH) {
            throw new IllegalArgumentException("tipo exceeds maximum length of " + MAX_TIPO_LENGTH);
        }
        if (descricao.length() > MAX_DESCRICAO_LENGTH) {
            throw new IllegalArgumentException("descricao exceeds maximum length of " + MAX_DESCRICAO_LENGTH);
        }
        if (!tipo.matches("[\\p{L}\\p{N}\\s\\-_]+")) {
            throw new IllegalArgumentException("tipo contains invalid characters");
        }
    }

    private String sanitize(String input, int maxLength) {
        String trimmed = input.strip();
        if (trimmed.length() > maxLength) {
            trimmed = trimmed.substring(0, maxLength);
        }
        return trimmed;
    }
}
