    private JLabel statusLabel;
    private JTextArea propertiesArea;

    public SecureObjectLoader() {
        initializeGUI();
    }

    private void initializeGUI() {
        frame = new JFrame("Secure Object Loader");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout(10, 10));

        statusLabel = new JLabel("No file loaded.");
        propertiesArea = new JTextArea(15, 40);
        propertiesArea.setEditable(false);

        JButton loadButton = new JButton("Load Object from File");
        loadButton.addActionListener(e -> loadObjectFromFile());

        frame.add(loadButton, BorderLayout.NORTH);
        frame.add(new JScrollPane(propertiesArea), BorderLayout.CENTER);
        frame.add(statusLabel, BorderLayout.SOUTH);
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    public void loadObjectFromFile() {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Select Serialized Object File");
        fileChooser.setFileSelectionMode(JFileChooser.FILES_ONLY);

        int result = fileChooser.showOpenDialog(frame);
        if (result != JFileChooser.APPROVE_OPTION) {
            return;
        }

        File selectedFile = fileChooser.getSelectedFile();

        if (!selectedFile.exists() || !selectedFile.isFile()) {
            showError("Selected path is not a valid file.");
            return;
        }

        if (!selectedFile.canRead()) {
            showError("Cannot read the selected file.");
            return;
        }

        if (selectedFile.length() > 10 * 1024 * 1024) {
            showError("File exceeds maximum allowed size of 10MB.");
            return;
        }

        try {
            Object loadedObject = deserializeFromFile(selectedFile);
            updateGUIWithObject(loadedObject);
        } catch (InvalidClassException e) {
            showError("Incompatible class version: " + sanitizeMessage(e.getMessage()));
        } catch (StreamCorruptedException e) {
            showError("File is not a valid serialized object.");
        } catch (ClassNotFoundException e) {
            showError("Unknown class in serialized data: " + sanitizeMessage(e.getMessage()));
        } catch (IOException e) {
            showError("I/O error reading file: " + sanitizeMessage(e.getMessage()));
        }
    }

    private Object deserializeFromFile(File file) throws IOException, ClassNotFoundException {
        try (FileInputStream fis = new FileInputStream(file);
             ObjectInputStream ois = new SafeObjectInputStream(fis)) {
            return ois.readObject();
        }
    }

    private void updateGUIWithObject(Object obj) {
        if (obj == null) {
            showError("Deserialized object is null.");
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Class: ").append(obj.getClass().getSimpleName()).append("\n\n");

        if (obj instanceof Map) {
            Map<?, ?> map = (Map<?, ?>) obj;
            sb.append("Properties:\n");
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                String key = sanitizeForDisplay(String.valueOf(entry.getKey()));
                String value = sanitizeForDisplay(String.valueOf(entry.getValue()));
                sb.append("  ").append(key).append(": ").append(value).append("\n");
            }
        } else {
            sb.append("toString():\n").append(sanitizeForDisplay(obj.toString()));
        }

        propertiesArea.setText(sb.toString());
        statusLabel.setText("Loaded: " + obj.getClass().getSimpleName());
    }

    private void showError(String message) {
        statusLabel.setText("Error: " + message);
        propertiesArea.setText("");
        JOptionPane.showMessageDialog(frame, message, "Load Error", JOptionPane.ERROR_MESSAGE);
    }

    private String sanitizeMessage(String message) {
        if (message == null) return "Unknown error";
        return message.replaceAll("[^a-zA-Z0-9 .,:_\\-]", "").substring(0, Math.min(message.length(), 200));
    }

    private String sanitizeForDisplay(String value) {
        if (value == null) return "null";
        if (value.length() > 500) {
            value = value.substring(0, 500) + "...[truncated]";
        }
        return value.replace("\r", "\\r").replace("\0", "\\0");
    }

    /**
     * Restricts deserialization to a known-safe allowlist of classes.
     * Rejects all other types to prevent deserialization exploits.
     */
    private static class SafeObjectInputStream extends ObjectInputStream {

        private static final java.util.Set<String> ALLOWED_CLASSES = new java.util.HashSet<>(java.util.Arrays.asList(
                "java.lang.String",
                "java.lang.Integer",
                "java.lang.Long",
                "java.lang.Double",
                "java.lang.Boolean",
                "java.util.HashMap",
                "java.util.ArrayList",
                "java.util.LinkedHashMap",
                "com.example.SafeDataObject"
        ));

        public SafeObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            String className = desc.getName();
            if (!ALLOWED_CLASSES.contains(className)) {
                throw new InvalidClassException("Unauthorized deserialization attempt", className);
            }
            return super.resolveClass(desc);
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(SecureObjectLoader::new);
    }
}
